TIMING_MARK_MIN_COLS = 5
TIMING_VENDOR_MIN_COLS = 13
TIMING_VENDOR_VENDOR_COL = 5
TIMING_VENDOR_KIND_COL = 6
TIMING_VENDOR_START_COL = 7
TIMING_VENDOR_END_COL = 8
